Ui.Script:
-- ref-GlobalStrings.lua values this file formats (the CastingBar.xml guarded idiom):
CONTESTED_TERRITORY = CONTESTED_TERRITORY or "Contested Territory";
FACTION_CONTROLLED_TERRITORY = FACTION_CONTROLLED_TERRITORY or "%s Territory"; -- Faction name
FREE_FOR_ALL_TERRITORY = FREE_FOR_ALL_TERRITORY or "PvP Area";
AUTOFOLLOWSTART = AUTOFOLLOWSTART or "Following %s.";
AUTOFOLLOWSTOP = AUTOFOLLOWSTOP or "You stop following %s.";

-- The ref's localization identity (UIParent.lua), so the AutoFollowStatus body below can
-- stay verbatim. Guarded like everything else here rather than leaning on UnitPopup.xml
-- happening to load first — a one-line helper is no place to acquire a load-order edge.
if ( not TEXT ) then
    TEXT = function(s) return s end
end

-- ── ref-FadingFrame.lua, verbatim ──────────────────────────────────────────────────────
function FadingFrame_SetFadeInTime(this, time)
    this.fadeInTime = time;
end
function FadingFrame_SetHoldTime(this, time)
    this.holdTime = time;
end
function FadingFrame_SetFadeOutTime(this, time)
    this.fadeOutTime = time;
end
function FadingFrame_OnLoad()
    this.fadeInTime = 0;
    this.holdTime = 0;
    this.fadeOutTime = 0;
    this:Hide();
end
function FadingFrame_Show()
    this.startTime = GetTime();
    this:Show();
end
function FadingFrame_OnUpdate()
    local elapsed = GetTime() - this.startTime;
    local fadeInTime = this.fadeInTime;
    if ( elapsed < fadeInTime ) then
        local alpha = (elapsed / fadeInTime);
        this:SetAlpha(alpha);
        return;
    end
    local holdTime = this.holdTime;
    if ( elapsed < (fadeInTime + holdTime) ) then
        this:SetAlpha(1.0);
        return;
    end
    local fadeOutTime = this.fadeOutTime;
    if ( elapsed < (fadeInTime + holdTime + fadeOutTime) ) then
        local alpha = 1.0 - ((elapsed - holdTime - fadeInTime) / fadeOutTime);
        this:SetAlpha(alpha);
        return;
    end
    this:Hide();
end

-- ── ref-ZoneText.xml <Script>, verbatim ────────────────────────────────────────────────
ZoneFadeInDuration = 0.5;
ZoneHoldDuration = 1.0;
ZoneFadeOutDuration = 2.0;

function SetZoneText(showPVPInfo)
    ZoneTextString:SetText(GetZoneText());
    local pvpType, factionName, isArena = GetZonePVPInfo();
    if ( pvpType == "friendly" ) then
        PVPInfoTextString:SetText(format(FACTION_CONTROLLED_TERRITORY, factionName));
        ZoneTextString:SetTextColor(0.1, 1.0, 0.1);
        SubZoneTextString:SetTextColor(0.1, 1.0, 0.1);
        PVPInfoTextString:SetTextColor(0.1, 1.0, 0.1);
        SubZoneTextString:SetPoint("TOP", "PVPInfoTextString", "BOTTOM", 0, 0);
    elseif ( pvpType == "hostile" ) then
        PVPInfoTextString:SetText(format(FACTION_CONTROLLED_TERRITORY, factionName));
        ZoneTextString:SetTextColor(1.0, 0.1, 0.1);
        SubZoneTextString:SetTextColor(1.0, 0.1, 0.1);
        PVPInfoTextString:SetTextColor(1.0, 0.1, 0.1);
        SubZoneTextString:SetPoint("TOP", "PVPInfoTextString", "BOTTOM", 0, 0);
    elseif ( pvpType == "contested" ) then
        PVPInfoTextString:SetText(CONTESTED_TERRITORY);
        ZoneTextString:SetTextColor(1.0, 0.7, 0);
        SubZoneTextString:SetTextColor(1.0, 0.7, 0);
        PVPInfoTextString:SetTextColor(1.0, 0.7, 0);
        SubZoneTextString:SetPoint("TOP", "PVPInfoTextString", "BOTTOM", 0, 0);
    else
        PVPInfoTextString:SetText("");
        ZoneTextString:SetTextColor(1.0, 0.9294, 0.7607);
        SubZoneTextString:SetTextColor(1.0, 0.9294, 0.7607);
        SubZoneTextString:SetPoint("TOP", "ZoneTextString", "BOTTOM", 0, 0);
    end
    if ( isArena ) then
        PVPArenaTextString:SetText(FREE_FOR_ALL_TERRITORY);
        SubZoneTextString:SetTextColor(1.0, 0.1, 0.1);
    else
        PVPArenaTextString:SetText("");
    end
    if ( not showPVPInfo ) then
        PVPInfoTextString:SetText("");
        SubZoneTextString:SetPoint("TOP", "ZoneTextString", "BOTTOM", 0, 0);
    end
end

-- ── ref-ZoneText.lua, verbatim ─────────────────────────────────────────────────────────
-- The auto-follow status line. Note it does NOT use the FadingFrame kit above: its own
-- OnUpdate rolls a plain linear alpha fade with no fade-in and no hold, started only on
-- AUTOFOLLOW_END. BEGIN is a full reset (fadeTime cleared, alpha restored, shown), which
-- is why a follow that switches subject needs no END first.
AUTOFOLLOW_STATUS_FADETIME = 4.0;

function AutoFollowStatus_OnLoad()
    this:RegisterEvent("AUTOFOLLOW_BEGIN");
    this:RegisterEvent("AUTOFOLLOW_END");
    this:RegisterEvent("PLAYER_ENTERING_WORLD");
end

function AutoFollowStatus_OnEvent(event)
    if ( event == "AUTOFOLLOW_BEGIN" ) then
        this.unit = arg1;
        this.fadeTime = nil;
        this:SetAlpha(1.0);
        AutoFollowStatusText:SetText(format(TEXT(AUTOFOLLOWSTART),this.unit));
        this:Show();
    end
    if ( event == "AUTOFOLLOW_END" ) then
        this.fadeTime = AUTOFOLLOW_STATUS_FADETIME;
        AutoFollowStatusText:SetText(format(TEXT(AUTOFOLLOWSTOP),this.unit));
        this:Show();
    end
    if ( event == "PLAYER_ENTERING_WORLD" ) then
        this:Hide();
    end
end

function AutoFollowStatus_OnUpdate(elapsed)
    if( this.fadeTime ) then
        if( elapsed >= this.fadeTime ) then
            this:Hide();
        else
            this.fadeTime = this.fadeTime - elapsed;
            local alpha = this.fadeTime / AUTOFOLLOW_STATUS_FADETIME;
            this:SetAlpha(alpha);
        end
    end
end

Scripts.OnLoad:
FadingFrame_OnLoad();
FadingFrame_SetFadeInTime(this, ZoneFadeInDuration);
FadingFrame_SetHoldTime(this, ZoneHoldDuration);
FadingFrame_SetFadeOutTime(this, ZoneFadeOutDuration);
this:RegisterEvent("ZONE_CHANGED");
this:RegisterEvent("ZONE_CHANGED_INDOORS");
this:RegisterEvent("ZONE_CHANGED_NEW_AREA");

Scripts.OnEvent:
local newText = GetZoneText();
if ( event == "ZONE_CHANGED" ) then
    this.zoneText = newText;
    return;
end
if ( newText ~= this.zoneText ) then
    this.zoneText = newText;
    if ( event == "ZONE_CHANGED_NEW_AREA" ) then
        SetZoneText(1);
    else
        SetZoneText();
    end
    FadingFrame_Show();
end

Scripts.OnLoad:
FadingFrame_OnLoad();
FadingFrame_SetFadeInTime(this, ZoneFadeInDuration);
FadingFrame_SetHoldTime(this, ZoneHoldDuration);
FadingFrame_SetFadeOutTime(this, ZoneFadeOutDuration);
this:RegisterEvent("ZONE_CHANGED");
this:RegisterEvent("ZONE_CHANGED_INDOORS");
this:RegisterEvent("ZONE_CHANGED_NEW_AREA");
PVPArenaTextString:SetTextColor(1.0, 0.1, 0.1);
SetZoneText(1);
SubZoneTextString:SetText(GetSubZoneText());

Scripts.OnEvent:
local text = SubZoneTextString:GetText();
local newText = GetSubZoneText();
if(text ~= newText) then
    SubZoneTextString:SetText(newText);
    SetZoneText(1);
    FadingFrame_Show();
end
